\u00e9s."},"hi":{"question":"\\u092e\\u0948\\u0902 \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 API \\u0915\\u0948\\u0938\\u0947 \\u0938\\u0947\\u091f\\u0905\\u092a \\u0915\\u0930 \\u0938\\u0915\\u0924\\u093e \\u0939\\u0942\\u0901?","answer":"\\u0938\\u0941\\u0930\\u0915\\u094d\\u0937\\u093f\\u0924 \\u0911\\u0928\\u0932\\u093e\\u0907\\u0928 \\u092d\\u0941\\u0917\\u0924\\u093e\\u0928 \\u0915\\u0947 \\u0932\\u093f\\u090f \\u0935\\u0930\\u094d\\u091a\\u0941\\u0905\\u0932 \\u0915\\u093e\\u0930\\u094d\\u0921 \\u0928\\u093f\\u0930\\u094d\\u092e\\u093e\\u0923 \\u0914\\u0930 \\u092a\\u094d\\u0930\\u092c\\u0902\\u0927\\u0928 \\u0915\\u094b \\u0938\\u0915\\u094d\\u0937\\u092e \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0947 \\u0932\\u093f\\u090f API \\u0915\\u0949\\u0928\\u094d\\u092b\\u093c\\u093f\\u0917\\u0930 \\u0915\\u0930\\u0947\\u0902\\u0964"}},"id":"67d10c70aa3b6"},"67d10cbbf267d":{"language":{"en":{"question":"Where can I view my transaction logs?","answer":"View and track all your transactions in the \\"Transaction Logs\\" section to stay updated on your financial activities."},"es":{"question":"\\u00bfD\\u00f3nde puedo ver mis registros de transacciones","answer":"Vea y realice un seguimiento de todas sus transacciones en la secci\\u00f3n \\"Registros de Transacciones\\" para mantenerse al d\\u00eda con sus actividades financieras."},"ar":{"question":"\\u0623\\u064a\\u0646 \\u064a\\u0645\\u0643\\u0646\\u0646\\u064a \\u0639\\u0631\\u0636 \\u0633\\u062c\\u0644\\u0627\\u062a \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u064a\\u061f","answer":"\\u0627\\u0639\\u0631\\u0636 \\u0648\\u062a\\u062a\\u0628\\u0639 \\u062c\\u0645\\u064a\\u0639 \\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\u0643 \\u0641\\u064a \\u0642\\u0633\\u0645 \\"\\u0633\\u062c\\u0644\\u0627\\u062a \\u0627\\u0644\\u0645\\u0639\\u0627\\u0645\\u0644\\u0627\\u062a\\" \\u0644\\u0644\\u0628\\u0642\\u0627\\u0621 \\u0639\\u0644\\u0649 \\u0627\\u0637\\u0644\\u0627\\u06